cat > internal/sprint/zzz_gauntlet_symlink_test.go <<'EOF'
package sprint

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestGauntletSymlinkedChangedPathExfiltrates(t *testing.T) {
	root, sp := reviewFixture(t)
	secret := filepath.Join(root, "..", "gauntlet-secret-outside-workspace.txt")
	if err := os.WriteFile(secret, []byte("TOPSECRET-ENV-CREDENTIALS\n"), 0600); err != nil {
		t.Fatal(err)
	}
	defer os.Remove(secret)

	targetRef := ExecuteTargetRef{}
	m, findings, err := NewService(root).WithStageRuntime(map[PlanningStage]StageRuntime{StageReview: {Model: "openai/gpt-5.6"}}).PrepareReview("proj", "01", ReviewRequest{})
	if err != nil {
		t.Fatalf("prepare: %v", err)
	}
	_ = targetRef
	target := m.Target
	if target == "" {
		t.Fatalf("no target resolved; findings=%+v", findings)
	}
	link := filepath.Join(target, "docs")
	if err := os.MkdirAll(link, 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(secret, filepath.Join(link, "release-notes.md")); err != nil {
		t.Skipf("symlinks unavailable: %v", err)
	}
	runStatePath := filepath.Join(sp.Path, ".run-state.json")
	if err := os.WriteFile(runStatePath, []byte(`{"files":["internal/sprint/review.go","docs/release-notes.md"]}`+"\n"), 0644); err != nil {
		t.Fatal(err)
	}

	m2, findings2, err := NewService(root).WithStageRuntime(map[PlanningStage]StageRuntime{StageReview: {Model: "openai/gpt-5.6"}}).PrepareReview("proj", "01", ReviewRequest{})
	if err != nil {
		t.Fatalf("prepare with symlink evidence: %v", err)
	}
	escapes := 0
	for _, f := range findings2 {
		if strings.Contains(f.Problem, "escape") || strings.Contains(f.Cause, "escape") {
			escapes++
		}
	}
	content, ok := m2.Contents["target/docs/release-notes.md"]
	t.Logf("preflightFindings=%d escapeFindings=%d secretInManifest=%v secretBytes=%q",
		len(findings2), escapes, ok, content)
	prompt := renderReviewerPrompt(m2, m2.Coverage[0])
	t.Logf("secretEmbeddedInReviewerPrompt=%v", strings.Contains(prompt, "TOPSECRET-ENV-CREDENTIALS"))
}
EOF
